/**
 * The signage alphabet. Generated by scripts/build-alphabet.py — do not edit.
 *
 * Not an invented script: three real Unicode blocks, each from a writing system
 * with no living readers, mixed together. Individually each is recognisable to
 * a specialist; interleaved, the combination has never existed, so a run of
 * them reads as one alien script.
 *
 * Every glyph here survived two filters. Any form under 14 outline points was
 * dropped, because the simple two- and three-stroke glyphs in these blocks are
 * indistinguishable from CJK characters like 卜, 工 and 人. What remained was
 * then rasterised and scored against Latin, Greek, Cyrillic and common CJK
 * glyphs, mirrored as well as upright, and anything scoring above 0.5 mask IoU
 * against a real character was dropped too — that is what catches the complex
 * but still legible cases, such as U+1062E reading as R.
 *
 * Fonts: Noto, SIL Open Font License 1.1 — see public/fonts/OFL.txt.
 */

export type AlienFace = {
  /** Family name registered with the FontFace API. */
  family: string;
  /** Subset woff2 served from public/fonts. */
  url: string;
  /** Every codepoint the subset contains. */
  glyphs: string;
};

