/** Flat pool of [family, glyph] pairs — what the sign renderer draws from. */
export const ALIEN_GLYPHS: Array<[family: string, glyph: string]> = ALIEN_FACES.flatMap((f) =>
  [...f.glyphs].map((g) => [f.family, g] as [string, string]),
);
